using System; using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Microsoft.IdentityModel.Tokens; namespace TuneHire.Api.Services { public interface IJwtService { string GenerateToken(int userId, string role); } public class JwtService : IJwtService { private readonly string _key; public JwtService(string key) { _key = key; } public string GenerateToken(int userId, string role) { var claims = new[] { new Claim(JwtRegisteredClaimNames.Sub, userId.ToString()), new Claim(ClaimTypes.Role, role) }; var creds = new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_key)), SecurityAlgorithms.HmacSha256); var token = new JwtSecurityToken(claims: claims, expires: DateTime.UtcNow.AddDays(7), signingCredentials: creds); return new JwtSecurityTokenHandler().WriteToken(token); } } }